package com.glassbox.chess.player; import com.glassbox.chess.ai.AIStrategy; import com.glassbox.chess.domain.*; import com.glassbox.chess.rule.MoveValidator; import com.glassbox.exception.GameLogicException; import java.util.*; import java.util.function.Supplier;
public class AIPlayer{private final AIStrategy strategy;public AIPlayer(AIStrategy strategy){this.strategy=strategy;}public Move determineMove(Board board,Supplier<Boolean> cancelled)throws GameLogicException{Move chosen=strategy.calculateMove(board,cancelled);if(cancelled.get())return null;List<Move> legal=MoveValidator.getLegalMoves(board,board.getGameState().turn);if(legal.isEmpty())return null;if(chosen==null||legal.stream().noneMatch(m->m.getFrom().equals(chosen.getFrom())&&m.getTo().equals(chosen.getTo())&&m.getClass()==chosen.getClass()))return legal.get(new Random().nextInt(legal.size()));return legal.stream().filter(m->m.getFrom().equals(chosen.getFrom())&&m.getTo().equals(chosen.getTo())&&m.getClass()==chosen.getClass()).findFirst().orElse(legal.get(0));}}
